import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第三十七卦 家人 風火家人 巽上離下","description":"周易 - 第三十七卦 家人 風火家人 巽上離下","frontmatter":{"title":"第三十七卦 家人 風火家人 巽上離下","description":"周易 - 第三十七卦 家人 風火家人 巽上離下"},"headers":[],"relativePath":"classics/zhouyi/038.md","filePath":"classics/zhouyi/038.md"}'),l={name:"classics/zhouyi/038.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="家人" tabindex="-1">家人 <a class="header-anchor" href="#家人" aria-label="Permalink to “家人”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>利女貞。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>家人，女正位乎內，男正位乎外，男女正，天地之大義也。家人有嚴君焉，父母之謂也。父父，子子，兄兄，弟弟，夫夫，婦婦，而家道正；正家而天下定矣。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>風自火出，家人；君子以言有物，而行有恆。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>閒有家，悔亡。象曰：閒有家，志未變也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>無攸遂，在中饋，貞吉。象曰：六二之吉，順以巽也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>家人嗃嗃，悔厲吉；婦子嘻嘻，終吝。象曰：家人嗃嗃，未失也；婦子嘻嘻，失家節也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>富家，大吉。象曰：富家大吉，順在位也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>王假有家，勿恤吉。象曰：王假有家，交相愛也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>有孚威如，終吉。象曰：威如之吉，反身之謂也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
